INSERT INTO email_templates (id,event_id,key,name,subject,body_html,created_at) VALUES (1,1,'confirmation','Submission confirmation','We received your proposal for {event_name}','<p>Hi {speaker_name},</p><p>We received "{talk_title}" for {event_name}. You can edit it from your portal until the call for proposals closes.</p>{portal_button}',1786305600);
INSERT INTO email_templates (id,event_id,key,name,subject,body_html,created_at) VALUES (2,1,'acceptance','Acceptance','Your talk has been accepted to {event_name}','<p>Hi {speaker_name},</p><p>Congratulations. Your session "{talk_title}" has been accepted at {event_name}. Please confirm your participation and complete your speaker profile.</p>{portal_button}',1786305600);
INSERT INTO email_templates (id,event_id,key,name,subject,body_html,created_at) VALUES (3,1,'decline','Decline','Update on your {event_name} proposal','<p>Hi {speaker_name},</p><p>Thank you for submitting "{talk_title}" to {event_name}. We are not able to include it this year. We had far more strong proposals than slots, and we would still love to see you at the event.</p>{#feedback}<p>{feedback}</p>{/feedback}',1786305600);
INSERT INTO email_templates (id,event_id,key,name,subject,body_html,created_at) VALUES (4,1,'schedule','Schedule notice','Your session is scheduled: {talk_title}','<p>Hi {first_name},</p><p>"{talk_title}" is scheduled for {session_time} in {room_name}. A calendar invitation is attached.</p>{portal_button}',1786305600);
